package br.com.onda;
import android.content.Context;import android.util.Base64;import java.net.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.*;import java.util.function.Consumer;
/** Downloads only an explicitly selected image, streams to disk and cancels on leaving the screen. */
final class WebImageFiles {
 static File cached(Context c,String raw){try{if(!WebImages.inline(raw))WebImages.image(raw);byte[] hash=MessageDigest.getInstance("SHA-256").digest(raw.getBytes(StandardCharsets.UTF_8));StringBuilder key=new StringBuilder();for(byte b:hash)key.append(String.format(Locale.ROOT,"%02x",b&255));File root=new File(c.getCacheDir(),"web-image-shares");root.mkdirs();return new File(root,key+".image");}catch(Exception e){throw new IllegalArgumentException(e);}}
 static File image(Context c,String raw,String userAgent,Consumer<HttpURLConnection> active)throws Exception{File file=cached(c,raw);if(file.isFile()&&file.length()>0){file.setLastModified(System.currentTimeMillis());return file;}File temp=File.createTempFile("selected-",".part",file.getParentFile());try{if(WebImages.inline(raw)){byte[] decoded=Base64.decode(raw.substring(raw.indexOf(',')+1),Base64.DEFAULT);try(OutputStream out=new FileOutputStream(temp)){out.write(decoded);}}else{String url=WebImages.image(raw);boolean done=false;for(int redirect=0;redirect<5;redirect++){if(Thread.currentThread().isInterrupted())throw new InterruptedIOException();URI uri=new URI(url);for(InetAddress address:InetAddress.getAllByName(uri.getHost()))if(address.isAnyLocalAddress()||address.isLoopbackAddress()||address.isLinkLocalAddress()||address.isSiteLocalAddress()||address.isMulticastAddress()||address.getAddress().length==16&&(address.getAddress()[0]&0xfe)==0xfc)throw new IOException("Endereço de imagem indisponível.");HttpURLConnection connection=(HttpURLConnection)new URL(url).openConnection();active.accept(connection);try{connection.setInstanceFollowRedirects(false);connection.setConnectTimeout(15000);connection.setReadTimeout(15000);connection.setRequestProperty("User-Agent",userAgent);connection.setRequestProperty("Accept","image/*");int code=connection.getResponseCode();if(code>=300&&code<400){url=WebImages.image(new URL(new URL(url),connection.getHeaderField("Location")).toString());continue;}if(code!=200)throw new IOException("A origem não disponibilizou a imagem (HTTP "+code+").");try(InputStream in=connection.getInputStream();OutputStream out=new FileOutputStream(temp)){byte[] bytes=new byte[65536];int n;while((n=in.read(bytes))!=-1){if(Thread.currentThread().isInterrupted())throw new InterruptedIOException();out.write(bytes,0,n);}}done=true;break;}finally{connection.disconnect();active.accept(null);}}if(!done)throw new IOException("Muitos redirecionamentos na imagem.");}if(Thread.currentThread().isInterrupted())throw new InterruptedIOException();if(temp.length()==0||!temp.renameTo(file))throw new IOException("Não foi possível guardar a imagem.");trim(file);return file;}finally{temp.delete();}}
 private static void trim(File keep){File[] files=keep.getParentFile().listFiles();if(files==null)return;Arrays.sort(files,Comparator.comparingLong(File::lastModified));long size=0;for(File file:files)size+=file.length();for(File file:files)if(!file.equals(keep)&&size>24*1024*1024){long bytes=file.length();if(file.delete())size-=bytes;}}
}
